func (a *Stat2SQL) CreateIndexes(ctx context.Context) error {
	for _, q := range stat2SQLIndexes {
		if _, err := a.db.Exec(ctx, q); err != nil {
			return err
		}
	}
	return nil
}

// Init creates table and indexes
func (a *Stat2SQL) Init(ctx context.Context) error {
	if err := a.CreateTable(ctx); err != nil {
		return err
	}
	return a.CreateIndexes(ctx)
}

// ResetSequence sets next id to max(id) + add (1 by default).
// Useful after insert with own ids: InsertFull, Upsert, InsertMany
func (a *Stat2SQL) ResetSequence(ctx context.Context, add ...int64) error {
	plus := int64(1)
	if len(add) > 0 {
		plus = add[0]
	}
	_, err := a.db.Exec(ctx, "select setval(pg_get_serial_sequence('stat2', 'id'), coalesce((select max(id) from stat2), 0) + $1, false)", plus)
	return err
}

// SetSequence sets next id
func (a *Stat2SQL) SetSequence(ctx context.Context, value int64) error {
	_, err := a.db.Exec(ctx, "select setval(pg_get_serial_sequence('stat2', 'id'), $1, false)", value)
	return err
}
